    <style>
        *{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#18212f;font:15px/1.5 Arial,sans-serif}.top{background:#123c2e;color:#fff;padding:12px max(24px,calc((100% - 940px)/2));display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;font-weight:700;letter-spacing:.02em}.brand img{display:block;width:52px;height:52px;object-fit:contain}.top-link{color:#fff;font-weight:600;text-decoration:none}.top-link:hover{text-decoration:underline}.wrap{max-width:760px;margin:42px auto;padding:0 18px}.card{background:white;border:1px solid #e1e6eb;border-radius:12px;padding:32px;box-shadow:0 8px 28px #1524380b}h1{margin:0 0 4px;font-size:27px}p.muted{color:#647084;margin:0 0 24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field{margin-bottom:18px}.field.full{grid-column:1/-1}label{display:block;font-weight:600;margin-bottom:7px}input,select{width:100%;padding:12px;border:1px solid #cfd6df;border-radius:7px;font:inherit;background:#fff}input:focus,select:focus{outline:2px solid #79aa96;border-color:#276b50}.error{color:#a12828;font-size:13px;margin-top:4px}.picker{position:relative}.picker-toggle{width:100%;padding:12px;text-align:left;background:white;border:1px solid #cfd6df;border-radius:7px;font:inherit;cursor:pointer;display:flex;justify-content:space-between}.picker-menu{display:none;position:absolute;z-index:5;left:0;right:0;top:calc(100% + 4px);max-height:250px;overflow:auto;background:white;border:1px solid #cfd6df;border-radius:7px;box-shadow:0 8px 20px #17263a20;padding:6px}.picker.open .picker-menu{display:block}.course-option{display:flex;gap:9px;align-items:flex-start;padding:8px;border-radius:5px;font-weight:400;cursor:pointer}.course-option:hover{background:#f3f7f5}.course-option input{width:auto;margin-top:4px}.empty{color:#697386;padding:10px}.actions{display:flex;justify-content:space-between;align-items:center;margin-top:24px}.btn{display:inline-block;border:0;border-radius:7px;background:#176044;color:#fff;padding:12px 18px;font-weight:700;font-size:15px;cursor:pointer;text-decoration:none}.btn:hover{background:#104c35}.link{color:#176044;font-weight:600}.notice{padding:12px;background:#eff6ff;border-radius:7px;margin-bottom:18px;color:#33445b}dialog{border:0;border-radius:12px;width:min(520px,calc(100% - 28px));padding:0;box-shadow:0 20px 70px #0005}dialog::backdrop{background:#14233199}.dialog-inner{padding:26px}.dialog-inner h2{margin:0 0 14px}.summary{background:#f5f7f8;border-radius:8px;padding:14px;margin:14px 0}.summary div{margin:4px 0}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.secondary{background:#e9edf0;color:#243343}@media(max-width:600px){.top{padding:10px 18px}.brand{gap:9px;font-size:14px}.brand img{width:44px;height:44px}.top-link{display:none}.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.card{padding:22px}.wrap{margin:22px auto}.actions{flex-direction:column;align-items:stretch;gap:14px}.actions .btn{order:-1;text-align:center}.actions .link{text-align:center}}
    </style>
</head>
<body>
<header class="top"><div class="brand"><img src="{{ asset('images/logo.png') }}" alt=""><span>MUKUBA UNIVERSITY</span></div><a class="top-link" href="{{ route('registration.lookup') }}">I have already registered</a></header>
<main class="wrap"><section class="card">
    <h1>Course registration</h1><p class="muted">Enter your details and select the courses for your programme.</p>
    @if ($errors->any())<div class="notice" role="alert">{{ $errors->first('course_ids') ?: 'Please correct the highlighted fields and try again.' }}</div>@endif
    <form id="registration-form" method="post" action="{{ route('registration.store') }}">
        @csrf
        <div class="grid">
            <div class="field"><label for="student_id">Student ID</label><input id="student_id" name="student_id" type="text" inputmode="numeric" pattern="[0-9]{8}" minlength="8" maxlength="8" title="Enter exactly 8 numbers" value="{{ old('student_id') }}" required>@error('student_id')<div class="error">{{ $message }}</div>@enderror</div>
            <div class="field"><label for="first_name">First name</label><input id="first_name" name="first_name" maxlength="15" value="{{ old('first_name') }}" required>@error('first_name')<div class="error">{{ $message }}</div>@enderror</div>
            <div class="field"><label for="middle_name">Middle name <span style="font-weight:400;color:#687588">(optional)</span></label><input id="middle_name" name="middle_name" maxlength="15" value="{{ old('middle_name') }}">@error('middle_name')<div class="error">{{ $message }}</div>@enderror</div>
            <div class="field"><label for="last_name">Last name</label><input id="last_name" name="last_name" maxlength="15" value="{{ old('last_name') }}" required>@error('last_name')<div class="error">{{ $message }}</div>@enderror</div>
            <div class="field"><label for="program_id">Programme</label><select id="program_id" name="program_id" required><option value="">Choose your programme</option>@foreach($programs as $program)<option value="{{ $program->id }}" @selected(old('program_id') == $program->id)>{{ $program->name }}</option>@endforeach</select>@error('program_id')<div class="error">{{ $message }}</div>@enderror</div>
            <div class="field full"><label>Courses</label><div id="course-picker" class="picker"><button type="button" class="picker-toggle" aria-expanded="false"><span id="course-label">Choose a programme first</span><span>⌄</span></button><div class="picker-menu" id="course-options"><div class="empty">Choose a programme to load courses.</div></div></div>@error('course_ids')<div class="error">{{ $message }}</div>@enderror<div id="course-errors"></div></div>
        </div>
        <div class="actions"><a class="link" href="{{ route('registration.lookup') }}">I have already registered</a><button class="btn" type="submit">Review registration</button></div>
    </form>
</section></main>
<dialog id="confirm-dialog"><div class="dialog-inner"><h2>Confirm your registration</h2><p>Check your student details and selected courses before submitting.</p><div class="summary" id="review-summary"></div><div class="dialog-actions"><button type="button" class="btn secondary" id="edit-registration">Go back</button><button type="button" class="btn" id="confirm-registration">Confirm and submit</button></div></div></dialog>
<script>
const studentIdInput=document.getElementById('student_id');
studentIdInput.addEventListener('input',()=>{studentIdInput.value=studentIdInput.value.replace(/\\D/g,'').slice(0,8)});
const programSelect=document.getElementById('program_id'),picker=document.getElementById('course-picker'),toggle=picker.querySelector('.picker-toggle'),options=document.getElementById('course-options'),label=document.getElementById('course-label'),form=document.getElementById('registration-form'),dialog=document.getElementById('confirm-dialog');
async function loadCourses(){options.innerHTML='<div class="empty">Loading courses…</div>';label.textContent='Loading courses…';if(!programSelect.value){options.innerHTML='<div class="empty">Choose a programme to load courses.</div>';label.textContent='Choose a programme first';return}try{const response=await fetch(@json(route('registration.courses', ['program' => 'PROGRAM_ID'])).replace('PROGRAM_ID',encodeURIComponent(programSelect.value)),{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const courses=await response.json();if(!courses.length){options.innerHTML='<div class="empty">No courses are available for this programme.</div>';label.textContent='No courses available';return}options.innerHTML=courses.map(c=>`<label class="course-option"><input type="checkbox" name="course_ids[]" value="${c.id}" checked data-code="${escapeHtml(c.code)}" data-title="${escapeHtml(c.title)}"><span><strong>${escapeHtml(c.code)}</strong> — ${escapeHtml(c.title)}</span></label>`).join('');options.querySelectorAll('input[type="checkbox"]').forEach(input=>input.addEventListener('change',updateLabel));updateLabel()}catch(e){options.innerHTML='<div class="empty">Courses could not be loaded. Please try again.</div>';label.textContent='Unable to load courses'}}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function updateLabel(){const n=options.querySelectorAll('input[type="checkbox"][name="course_ids[]"]:checked').length;label.textContent=n?`${n} course${n===1?'':'s'} selected`:'No courses selected'}
programSelect.addEventListener('change',loadCourses);toggle.addEventListener('click',()=>{picker.classList.toggle('open');toggle.setAttribute('aria-expanded',picker.classList.contains('open'))});document.addEventListener('click',e=>{if(!picker.contains(e.target)){picker.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});
form.addEventListener('submit',event=>{event.preventDefault();document.getElementById('course-errors').innerHTML='';if(!form.reportValidity())return;const chosen=[...options.querySelectorAll('input[type="checkbox"][name="course_ids[]"]:checked')];if(!chosen.length){document.getElementById('course-errors').innerHTML='<div class="error">Select at least one course.</div>';picker.classList.add('open');return}const full=[document.getElementById('first_name').value,document.getElementById('middle_name').value,document.getElementById('last_name').value].filter(Boolean).join(' ');const programme=programSelect.options[programSelect.selectedIndex].text;document.getElementById('review-summary').innerHTML=`<div><strong>Student ID:</strong> ${escapeHtml(document.getElementById('student_id').value)}</div><div><strong>Student:</strong> ${escapeHtml(full)}</div><div><strong>Programme:</strong> ${escapeHtml(programme)}</div><div><strong>Courses (${chosen.length}):</strong><ul>${chosen.map(c=>`<li>${escapeHtml(c.dataset.code)} — ${escapeHtml(c.dataset.title)}</li>`).join('')}</ul></div>`;dialog.showModal()});document.getElementById('edit-registration').addEventListener('click',()=>dialog.close());document.getElementById('confirm-registration').addEventListener('click',()=>form.submit());
if(programSelect.value)loadCourses();
</script>
</body></html>
